func ProcessBlockHeader(ctx context.Context, beaconState state.BeaconState, block interfaces.ReadOnlySignedBeaconBlock) (state.BeaconState, error) {
    if err := blocks.BeaconBlockIsNil(block); err != nil { return nil, err }
    bodyRoot, err := block.Block().Body().HashTreeRoot()
    if err != nil { return nil, err }
    parentRoot := block.Block().ParentRoot()
    beaconState, err = ProcessBlockHeaderNoVerify(ctx, beaconState, block.Block().Slot(), block.Block().ProposerIndex(), parentRoot[:], bodyRoot[:])
    if err != nil { return nil, err }
    // Verify proposer signature.
    sig := block.Signature()
    if err := VerifyBlockSignature(beaconState, block.Block().ProposerIndex(), sig[:], block.Block().HashTreeRoot); err != nil {
        return nil, err
    }
    return beaconState, nil
}

func ProcessBlockHeaderNoVerify(ctx context.Context, beaconState state.BeaconState, slot primitives.Slot, proposerIndex primitives.ValidatorIndex, parentRoot, bodyRoot []byte) (state.BeaconState, error) {
    if beaconState.Slot() != slot { return nil, fmt.Errorf("state slot: %d is different than block slot: %d", beaconState.Slot(), slot) }
    idx, err := helpers.BeaconProposerIndex(ctx, beaconState)
    if err != nil { return nil, err }
    if proposerIndex != idx { return nil, fmt.Errorf("proposer index: %d is different than calculated: %d", proposerIndex, idx) }
    parentHeader := beaconState.LatestBlockHeader()
    if parentHeader.Slot >= slot { return nil, fmt.Errorf("block.Slot %d must be greater than state.LatestBlockHeader.Slot %d", slot, parentHeader.Slot) }
    parentHeaderRoot, err := parentHeader.HashTreeRoot()
    if err != nil { return nil, err }
    if !bytes.Equal(parentRoot, parentHeaderRoot[:]) {
        return nil, fmt.Errorf("parent root %#x does not match the latest block header signing root in state %#x", parentRoot, parentHeaderRoot[:])
    }
    proposer, err := beaconState.ValidatorAtIndexReadOnly(idx)
    if err != nil { return nil, err }
    if proposer.Slashed() { return nil, fmt.Errorf("proposer at index %d was previously slashed", idx) }
    if err := beaconState.SetLatestBlockHeader(&ethpb.BeaconBlockHeader{Slot: slot, ProposerIndex: proposerIndex, ParentRoot: parentRoot, StateRoot: params.BeaconConfig().ZeroHash[:], BodyRoot: bodyRoot}); err != nil {
        return nil, err
    }
    return beaconState, nil
}

